    async function kcManualTargets(refresh=false){clearTimeout(kc.manual.targetTimer);try{const data=await kcGet('/targets'+(refresh?'?refresh=1':''));kc.manual.targets=Array.isArray(data.items)?data.items:[];kc.manual.targetLoading=!!data.loading;kc.manual.targetError=data.error||null;}catch(error){kc.manual.targets=null;kc.manual.targetLoading=false;kc.manual.targetError=error.code||'manual_admission_unavailable';}kcManualRender();if(kc.manual.targetLoading&&kcVisible())kc.manual.targetTimer=setTimeout(()=>kcManualTargets(),2000);}
