    async function kcManualLoadRun(){const job=kc.manual.job;if(!job||!job.write_run_id||kc.manual.run)return;try{const run=await kcGet('/runs/'+encodeURIComponent(job.write_run_id));if(kc.manual.job&&kc.manual.job.job_id===job.job_id){kc.manual.run=run;kcManualRender();}}catch(_){kcMessage('Подробности записи WB пока недоступны. Нажмите «Обновить данные».');}}
